package com.company.skillplatform.user.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="org_team_member",uniqueConstraints=@UniqueConstraint(name="uk_org_team_member",columnNames={"team_id","user_id"})) public class OrgTeamMemberEntity extends BaseJpaEntity{@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="team_id",nullable=false)private OrgTeamEntity team;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id",nullable=false)private IamUserEntity user;@Column(name="membership_type",nullable=false,length=32)private String membershipType;@Column(nullable=false,length=32)private String status;@Column(name="last_seen_sync_run_id")private Long lastSeenSyncRunId;@Column(name="last_synced_at")private Instant lastSyncedAt;protected OrgTeamMemberEntity(){}public OrgTeamMemberEntity(OrgTeamEntity t,IamUserEntity u){team=t;user=u;membershipType="MEMBER";status="ACTIVE";}public OrgTeamEntity getTeam(){return team;}public IamUserEntity getUser(){return user;}public String getMembershipType(){return membershipType;}public String getStatus(){return status;}public Long getLastSeenSyncRunId(){return lastSeenSyncRunId;}public void sync(Instant now,Long runId){status="ACTIVE";lastSeenSyncRunId=runId;lastSyncedAt=now;}public void deactivate(){status="INACTIVE";}}
